package com.shatteredpixel.shatteredpixeldungeon.apd.mechanics;

import com.shatteredpixel.shatteredpixeldungeon.Dungeon;
import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero;
import com.shatteredpixel.shatteredpixeldungeon.items.potions.Potion;

/** Known consumable effects only; does not identify, drink, shatter, heal or generate clouds. */
public final class PotionExplanation {
    private PotionExplanation(){}
    private static String n(float value){return ObfuscationExplanation.number(value);}
    private static String timed(String effect,float duration){return "Offers "+effect+" for "+n(duration)+" game-time units before normal resistance and reapplication rules. The ordinary prolonging path preserves a longer existing scheduled duration rather than adding another full duration. This is time in the game, not real-world seconds.";}
    public static String details(Potion potion,Hero hero){
        String text=effect(potion,hero);
        if(text.isEmpty())return "";
        return "_Known potion effect_\n"+text+" Where ordinary drinking is available, it spends one game-time unit and consumes the potion; special targeting and shattering paths retain their own action rules. Viewing this explanation never drinks, throws or identifies an unknown potion.";
    }
    /** Effect body only, so an imbued food is not described as a separate potion-drinking action. */
    public static String effect(Potion potion,Hero hero){
        if(potion==null||!potion.isKnown())return "";
        String text;
        switch(potion.getClass().getSimpleName()){
            case "ElixirOfMight":text="Permanently adds one base Strength point and resets its temporary maximum-health contribution to five remaining level-up steps. At full strength the base contribution is round(4 + (15 + 5 × hero level) / 20). "+(hero==null?"":"At the current hero level that is "+com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfMight.HTBoost.boost(15+5*hero.lvl)+" base maximum-HP points before run modifiers. ")+"The remaining contribution is round(remaining level steps × that full contribution / 5). Each hero level-up spends one step; ordinary turns do not spend steps. Reapplication resets the five-step reserve rather than adding another independent stack. Maximum-health updates and other modifiers retain their normal behavior.";break;
            case "ElixirOfArcaneArmor":text="Offers Arcane Armor strength 5 + floor(hero level / 2), with an 80-unit strength-decay interval. "+(hero==null?"":"Current offer: "+(5+hero.lvl/2)+" protection points. ")+"The strength is the upper bound of a separate protection roll against supported magical damage, not guaranteed absorption on every hit or immunity to all magic. Each decay step loses one strength point. The effect's existing strength/interval replacement rule determines whether a new offer replaces an old one.";break;
            case "ElixirOfAquaticRejuvenation":text="Offers a stored base healing reserve of round(maximum HP × 1.5). "+(hero==null?"":"At current maximum HP: "+Math.round(hero.HT*1.5f)+" base HP in the offered reserve. ")+"A larger existing reserve is preserved instead of adding the whole offer. While grounded in water and missing HP, each update offers maximum HP / 50, bounded by at least one point, the remaining reserve and missing HP, with probabilistic rounding of any fraction. Run healing modifiers apply separately; the base amount is spent from the reserve even when modified healing differs. Standing on dry ground, flying or full health pauses that healing opportunity without spending the reserve as ordinary duration.";break;
            case "ElixirOfHoneyedHealing":text="Uses the regular healing potion's cure list and gradual base pool, integer part of 0.8 × maximum HP + 14, with the same Vial, challenge and healing-modifier rules. Drinking also offers 150 hunger units and triggers supported food-eaten talent effects. That is hunger relief, not 150 extra HP or another inventory food item. Shattering on a character uses its cure/heal path; an eligible hostile bee can also become allied under the existing bee rule.";break;
            case "ElixirOfFeatherFall":text="Offers a separate Feather Fall effect for "+n(com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfFeatherFall.FeatherBuff.DURATION)+" turns. A supported fall uses its protection and subtracts "+n(com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfFeatherFall.FeatherBuff.FALL_COST)+" additional turns from the remaining protection. Time passing can expire it first; this is not an unconditional promise of five future protected falls. It does not grant ordinary flight, teleportation, free floor transitions or permanent immunity to every source of falling damage.";break;
            case "ElixirOfDragonsBlood":text="Sets the supported Fire Imbue resource to "+n(FireImbue.DURATION)+" game-time units. Reapplying replaces this resource with the stated duration rather than adding a second full stack. Supported fire immunity and attack ignition use the imbue's existing rules; its duration is not flat extra physical damage or immunity to all heat-looking magic.";break;
            case "ElixirOfToxicEssence":text="Sets Toxic Imbue's resource to "+n(ToxicImbue.DURATION)+" game-time units, replacing its previous resource rather than adding another full duration. Its poison immunity, toxic emission and damage effects retain their own rules. This is not a universal percentage damage bonus or immunity to every cloud and status.";break;
            case "ElixirOfIcyTouch":text=timed("Frost Imbue",FrostImbue.DURATION)+" Its supported freezing interactions, chances and immunities remain separate from this duration. The effect does not guarantee every target is frozen for the entire imbue duration.";break;
            case "BlizzardBrew":case "InfernalBrew":text="The initial supported 3 × 3 impact placement totals 1080 cloud-volume units, moving solid-neighbor shares into the center. The cloud uses its own spreading, terrain, exposure and damage/status rules. Volume is not fixed damage or a guaranteed number of affected turns for each character; allies and the hero retain their normal risks.";break;
            case "ShockingBrew":text="Seeds 20 units of electricity on each cell reachable from the impact through the existing non-solid distance map within 3 steps. This is a terrain-bounded area, not a guaranteed radius through walls. Electricity volume, exposure and final damage are separate; the hero and allies keep their normal risks.";break;
            case "CausticBrew":text="Checks cells reachable through the existing non-solid distance map within 3 steps and offers Ooze to characters there for "+n(Ooze.DURATION)+" game-time units before its normal status rules. It is not a fixed direct damage amount or a status duration guaranteed through resistance and cleansing. The hero and allies can be affected.";break;
            case "AquaBrew":text="Activates the existing geyser effect at the impact cell. It can spread water through the supported nearby terrain, extinguish supported effects and push eligible characters with force 2 under collision rules. Fiery creatures have the geyser's separate damage branch. Push force is not guaranteed displacement through walls, and area effects are not automatically harmless to the hero or allies. Inspection does not create water or choose a knockback direction.";break;
            case "UnstableBrew":text="Selects an effect from its existing weighted regular-potion table. Drinking rerolls throw-only effects; shattering rerolls outcomes that are neither required nor supported throw effects. The weights are conditional on the chosen use and challenges, so the result is not uniform across all potion types. Pharmacophobia removes Healing from the drinking selection. Each selected potion uses its own effect, target and duration rules; inspection does not choose an outcome or advance randomness.";break;
            case "PotionOfHealing":text="The base healing pool is the integer part of 0.8 × maximum HP + 14. "+(hero==null?"":"At current maximum HP, that is "+(int)(.8f*hero.HT+14)+" base HP before Vial, healing modifiers and missing-health limits. ")+"It is delivered by Healing's gradual pool, not all restored instantly. The setup also cures Poison, Cripple, Weakness, Vulnerable, Bleeding, Blindness, Drowsy, Slow and Vertigo through its existing cure list. Pharmacophobia replaces the healing branch with its poison effect. Inspect the active Healing effect for its actual remaining pool and next scheduled offer; this panel never spends fractional healing credit.";break;
            case "PotionOfShielding":text="Offers a Barrier of the integer part of 0.6 × maximum HP + 10. "+(hero==null?"":"At current maximum HP, that is "+(int)(.6f*hero.HT+10)+" shield points. ")+"A stronger existing Barrier is kept rather than adding the full offer. This does not heal HP or increase maximum HP; normal shield decay and damage consumption remain. Pharmacophobia uses its poison branch instead.";break;
            case "PotionOfStrength":text="Permanently adds one point to base Strength. A point is a score, not a percentage increase to all damage or an immediate HP heal. Equipment requirements and any strength-based bonuses use their own formulas; this potion does not itself identify or upgrade a weapon.";break;
            case "PotionOfExperience":text="Offers the hero's current full level-experience requirement as experience. "+(hero==null?"":"Current offer: "+hero.maxExp()+" experience points. ")+"Existing saved progress, maximum-level handling and experience-related effects still apply. This is not a permanent experience-gain multiplier or automatic talent selection.";break;
            case "PotionOfInvisibility":text=timed("Invisibility",Invisibility.DURATION)+" Supported attacks and other breaking actions still end invisibility. Sensing and special enemy detection remain separate; invisibility is not immunity to every damage source.";break;
            case "PotionOfHaste":text=timed("Haste",Haste.DURATION)+" Haste multiplies movement rate by 3, dividing an otherwise unchanged walking step's time by 3. Attack and recharge rates are separate.";break;
            case "PotionOfStamina":text=timed("Stamina",Stamina.DURATION)+" Stamina multiplies supported movement rate by 1.5, rather than all attack damage or all action rates. Other movement modifiers retain their own combination rules.";break;
            case "PotionOfLevitation":text=timed("Levitation",Levitation.DURATION)+" Supported ground hazards and terrain use the existing flying rules. Shattering instead seeds 1000 units of Confusion Gas. Gas volume is not 1000 turns of guaranteed confusion; spreading, concentration and terrain determine exposure.";break;
            case "PotionOfMindVision":text=timed("Mind Vision",MindVision.DURATION)+" Eligible creatures are sensed under the normal Mind Vision exclusions. This does not reveal every item's properties, search every wall or make projectile paths ignore solid terrain.";break;
            case "PotionOfMagicalSight":text=timed("Magical Sight",MagicalSight.DURATION)+" Magical sensing has its own visibility and exclusion rules. Its duration is not a tile radius, and a visible target can still be blocked for a physical projectile.";break;
            case "PotionOfPurity":text=timed("supported gas and environmental-cloud immunity",BlobImmunity.DURATION)+" Shattering clears its supported cloud types within the existing terrain-reachable area. It is not permanent immunity to every status effect or every magical attack.";break;
            case "PotionOfToxicGas":case "PotionOfParalyticGas":text="Shattering seeds 1000 units of its stated gas. This is cloud volume, not damage points or a guarantee of 1000 turns of a status effect on each character. Spread, concentration, terrain, exposure, resistance and the gas's own formulas determine its effects. The hero and allies retain normal exposure risks.";break;
            case "PotionOfLiquidFlame":text="Shattering seeds 2 units of fire on each eligible non-solid cell in the impact cell's 3 × 3 footprint. Fire volume is not guaranteed direct damage or two safe turns before burning. Terrain flammability, exposure, immunity and Burning's own formulas determine the outcome; nearby allies can be affected.";break;
            case "PotionOfFrost":text="Shattering seeds 10 units of freezing effect on each eligible non-solid cell in a 3 × 3 impact footprint. Cloud volume is not damage or the duration of every character's frozen state. Freezing, terrain, carried-item protection, resistance and thawing keep their normal rules.";break;
            case "PotionOfSnapFreeze":text="The impact checks the center and its eight immediate neighbors, excluding solid cells. It applies the existing immediate freezing effect and offers Roots for "+n(Roots.DURATION*2)+" game-time units before normal resistance and reapplication. Rooting blocks ordinary movement rather than all attacks; freezing and thawing keep their separate rules.";break;
            case "PotionOfMastery":text="Permanently reduces one eligible weapon or armor's Strength requirement by 2 points through its mastery flag. It cannot stack that flag on the same item or apply it to the Spirit Bow. This does not add 2 upgrade levels, base Strength, damage points or armor protection, and it does not identify hidden properties.";break;
            case "PotionOfEarthenArmor":text="Offers Barkskin strength 2 + floor(hero level / 3) with a 50-unit strength-decay interval. "+(hero==null?"":"At current hero level, the offered strength is "+(2+hero.lvl/3)+" protection points. ")+"That strength is the maximum of a separate random physical protection roll, not guaranteed blocked damage on every hit. Stronger existing Barkskin uses its normal replacement rule; each decay step loses one strength point, not the entire effect after 50 turns.";break;
            case "PotionOfCleansing":text="Removes supported negative effects, excluding ally-control effects and Lost Inventory. Existing Hunger is satisfied by 450 hunger units under the normal hunger rules. It then offers the existing Cleansing protection for 5 game-time units. These are separate resources and rules, not 450 HP of healing or immunity to every possible effect. The effect does not restore a lost backpack or erase an ally relationship.";break;
            case "PotionOfCorrosiveGas":text="The initial 3 × 3 gas placement totals 225 volume units, moving the shares for solid neighbors into the center. Starting corrosion strength is 2 + floor(scaling dungeon depth / 5). "+(hero==null?"":"For the current scaling depth, that is "+(2+Dungeon.scalingDepth()/5)+" strength points before later gas/status rules. ")+"Volume, corrosion strength and final HP damage are separate quantities. Exposure, spreading, resistance and the active Corrosion effect determine later damage; allies are not automatically protected.";break;
            case "PotionOfShroudingFog":text="The initial 3 × 3 fog placement totals 1620 volume units, moving solid-neighbor shares to the center. The cloud changes supported visibility under its existing rules; volume is not a guaranteed number of turns or a percentage chance to evade every attack. It does not automatically search hidden doors or identify items.";break;
            case "PotionOfStormClouds":text="The initial 3 × 3 placement totals 1080 cloud-volume units, moving solid-neighbor shares into the center. Its water and electrical interactions use the existing cloud and terrain rules. Volume is not fixed direct damage, a duration on every target or guaranteed protection for the hero.";break;
            case "PotionOfDragonsBreath":text="The supported breath cone reaches at most 6 tiles across 60 degrees, bounded by its targeting and solid-terrain rules. Eligible cells can be ignited; affected characters receive their normal burning treatment and a 5-unit Cripple offer. Fire damage, resistance and terrain interactions remain separate; cone size is not a fixed damage amount. Its selection and consumption path differs from ordinary immediate drinking.";break;
            case "PotionOfDivineInspiration":text="Adds 2 bonus talent points to one eligible selected tier under the existing entitlement rule. Previously boosted tiers cannot be boosted again by the same tracker rule, and normal tier/class availability still applies. This does not train every talent, remove rank limits or identify equipment. Selecting a tier and spending its points remain separate player choices.";break;
            default:return "";
        }
        return text;
    }
}
